class UnionFind:
    def __init__(self, n):
        self.parent = list(range(n))
        self.rank = [0] * n
        self.size = [1] * n

    def find(self, u):
        if self.parent[u] != u:
            self.parent[u] = self.find(self.parent[u])
        return self.parent[u]

    def union(self, u, v):
        root_u = self.find(u)
        root_v = self.find(v)
        if root_u != root_v:
            if self.rank[root_u] > self.rank[root_v]:
                self.parent[root_v] = root_u
                self.size[root_u] += self.size[root_v]
            else:
                self.parent[root_u] = root_v
                self.size[root_v] += self.size[root_u]
                if self.rank[root_u] == self.rank[root_v]:
                    self.rank[root_v] += 1
            return True
        return False

def solve(n, m, paths):
    uf = UnionFind(n)
    edges = []
    for i in range(m):
        a, b, l = paths[i]
        edges.append((l, a - 1, b - 1, i))
    edges.sort()

    result = [-1] * m
    longest_path = 0
    for i in range(m):
        l, a, b, idx = edges[i]
        if uf.union(a, b):
            if uf.size[uf.find(a)] % 2 == 1:
                longest_path = l
                result[idx] = longest_path
            else:
                result[idx] = -1
        else:
            result[idx] = -1

    return result

# Read input
n, m = map(int, input().split())
paths = [list(map(int, input().split())) for _ in range(m)]

# Solve the problem
result = solve(n, m, paths)

# Output the results
for res in result:
    print(res)
